+            kept exactly as sent. Retry to check; it cannot make a second copy.
+          </Text>
+        ) : null}
+        <SmallButton
+          tone="primary"
+          label={
+            saving ? "Saving" : existing ? "Save details" : "Create program"
+          }
+          onPress={submit}
+          disabled={(!locked && invalid) || saving || conflicts.length > 0}
